sql.if:
AND (


            c.owner_actor_id = #{actorId}


            EXISTS (
                SELECT 1
                FROM organization_membership owner_membership
                WHERE owner_membership.tenant_id = c.tenant_id
                  AND owner_membership.actor_id = c.owner_actor_id
                  AND owner_membership.status = 'ACTIVE'
                  AND owner_membership.department_id IN

                      #{departmentId}

            )



        OR EXISTS (
            SELECT 1
            FROM crm_lead_collaborator collaborator
            WHERE collaborator.tenant_id = c.tenant_id
              AND collaborator.lead_id = c.id
              AND collaborator.actor_id = #{actorId}

                AND collaborator.access_level = 'WRITE'

        )

)

mapper.select:
SELECT distance_query.*
FROM (
    SELECT c.*,
           ROUND(
               6371000 * 2 * ASIN(SQRT(
                   POWER(SIN(RADIANS(address.latitude - #{latitude}) / 2), 2)
                   + COS(RADIANS(#{latitude})) * COS(RADIANS(address.latitude))
                   * POWER(SIN(RADIANS(address.longitude - #{longitude}) / 2), 2)
               ))
           ) AS distance_meters
    FROM crm_lead c
    JOIN crm_lead_address address
      ON address.tenant_id = c.tenant_id
     AND address.lead_id = c.id
     AND address.is_primary = 1
     AND address.latitude IS NOT NULL
     AND address.longitude IS NOT NULL
     AND address.latitude BETWEEN #{minLatitude} AND #{maxLatitude}



     AND (address.longitude >= #{minLongitude}
          OR address.longitude <= #{maxLongitude})


     AND address.longitude BETWEEN #{minLongitude} AND #{maxLongitude}



    WHERE c.tenant_id = #{tenantId}
      AND c.status IN ('ACTIVE', 'CONVERTED')

) distance_query
WHERE distance_query.distance_meters <= #{radiusMeters}
ORDER BY distance_query.distance_meters ASC, distance_query.id ASC

SELECT c.id AS lead_id, c.name, c.phone_number, c.telephone, c.job_title, c.email, c.website, c.description, c.next_contact_time, c.is_locked AS locked, c.deal_status, c.status, c.created_time, c.updated_time FROM crm_lead c WHERE c.tenant_id = #{tenantId} AND c.id IN
#{leadId}
ORDER BY c.id ASC

SELECT field_value.lead_id, field_definition.field_code, field_value.scalar_value FROM crm_lead_field_value field_value JOIN custom_field_definition field_definition ON field_definition.tenant_id = field_value.tenant_id AND field_definition.object_type = field_value.object_type AND field_definition.id = field_value.field_id WHERE field_value.tenant_id = #{tenantId} AND field_value.object_type = 'LEAD' AND field_value.lead_id IN
#{leadId}
AND field_definition.field_code IN
#{fieldCode}
ORDER BY field_value.lead_id ASC, field_definition.field_code ASC
